  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  brush.noFill();
  brush.fillBleed(0.5);
  brush.fillTexture(1, true);
  brush.vertex(0, 0);
  brush.vertex(200, 100);
  brush.vertex(400, 0);
  brush.endShape(true);

  brush.noFill();
  brush.fillTexture(1, false);
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(400, 200);
  brush.endShape(true);

  brush.fillBleed(1);
  brush.beginShape(curvature);
  brush.vertex(100, 100);
  brush.vertex(100, 400);
  brush.vertex(300, 400);
  brush.endShape(true);
  brush.fill(1);
  brush.vertex(150, 100);
  brush.vertex(150, 400);
  brush.vertex(250, 400);
  brush.endShape(true);

  brush.fill(0, 0, 100, 50);
  brush.vertex(0, 0);
  brush.vertex(0, 400);
  brush.vertex(400, 400);
  brush.endShape(true);
  brush.vertex(200, 300);
  brush.vertex(300, 250);
  brush.vertex(400, 300);
  brush.endShape(true);

  brush.fillBleed(1);
  brush.beginShape(curvature);
  brush.vertex(100, 100);
  brush.vertex(100, 400);
  brush.vertex(300, 400);
  brush.endShape(true);
  brush.fill(0, 0, 100, 50);
  brush.vertex(250, 100);
  brush.vertex(350, 250);
  brush.vertex(400, 300);
  brush.endShape(true);
}

