const soloRender = false;
if (soloRender) {
  require('./frame_processor.js');
}

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  if (!soloRender) { return; }

  background('#d8e3d2');
  brush.fillBleed(0.6);
  brush.circle(200, 200, 50);

  // sunset's radius 100px
  brush.fill(0, 60, 120, 50);
  brush.circle(200, 100, 100);

  // tree's radius 25px
  brush.fill(80, 150, 0);
  brush.circle(200, 220, 25);

  brush.fill(10, 80, 160);
  brush.circle(200, 240, 25);
  brush.fill(10, 60, 160);
  brush.circle(190, 230, 25);

  // detached tree
  brush.fill(10, 80, 160);
  brush.circle(220, 240, 25);
  brush.fill(10, 60, 160);
  brush.circle(210, 230, 25);

  // horse
  brush.fill(50, 30, 150, 200);
  brush.beginShape();
  brush.vertex(205, 180);
  brush.vertex(225, 150);
  brush.vertex(245, 200);
  brush.vertex(235, 250);
  brush.vertex(245, 230);
  brush.vertex(220, 215);
  brush.endShape();

  brush.fill(85, 135, 155);
  brush.vertex(195, 170);
  brush.vertex(180, 240);
  brush.vertex(200, 260);
  brush.vertex(170, 225);
  brush.vertex(170, 205);
  brush.endShape(true);
}
```

