// Painting the scene
let max_red = 150, max_green = 150, max_blue = 230;
let pixel_red, pixel_green, pixel_blue;

draw = function () {
  background("#e08a72");
  paint();
};

paint = function() {
  // Draw the sky
  brush.fill(0, 0, 50);  
  brush.beginShape();
  brush.vertex(0, 0); // Top left corner, can do the rest of the drawing like this
  brush.vertex(400, 0); // Top right corner
  brush.vertex(400, 400); // bottom right
  brush.vertex(0, 400); // bottom left
  brush.endShape();

  // Draw the hills
  brush.fill(30, 150, 150);
  brush.beginShape();
  brush.vertex(0, 200); // create a starting point for the hills
  brush.vertex(200, 200); // (0,150)
  brush.vertex(400, 200); // (200,150)
  brush.endShape();

  // Draw the clouds above the hills
  brush.fill("#cccccc");
  brush.beginShape();
  brush.vertex(0, 450);
  brush.vertex(200, 400); // (450, 450)
  brush.vertex(400, 450);
  brush.endShape();

  // Draw the sun
  brush.fill(max_red, max_green, max_blue);  
  brush.beginShape();  
  brush.vertex(0, 200);
  brush.vertex(100, 100);  
  brush.vertex(200, 200);
  brush.endShape();
};
