  'use strict';
  const p5 = window.p5;

  let sketch = {
    setup: function () {
      createCanvas(400, 400, WEBGL);
      brush.scaleBrushes(2);
      noLoop();
    },
    draw: function () {
      background("#f4efe4");
      translate(-width / 2, -height / 2);
      if (p5.yahoo) {
        p5.yahoo.extend(p5, {e: 0});
      }
      let sky = '#a8d8ff';
      brush.fillStyle(sky);
      brush.fillRect(0, 0, width, height);
      brush.fillTexture(0.5, 0);
      brush.beginShape();
      for (let i = 0; i < 10; i++) {
        brush.vertex(i * 30, 0);
      }
      brush.endShape(true);
      let hills = '#559800';
      brush.fillStyle(hills);
      brush.fillTexture(0.8, 0);
      brush.fillRect(0, 300, 400, 100);
      brush.fillTexture(0.8, 1);
      brush.beginShape();
      for (let i = 0; i < 10; i++) {
        brush.vertex(i * 30, 310);
      }
      brush.endShape(true);
      brush.noFill();
      brush.fillBleed(0.8);
      let sun = '#ff4500';
      brush.fillStyle(sun);
      brush.fillTexture(1, 1);
      brush.beginShape();
      for (let i = 0; i < 20; i++) {
        brush.vertex(i * 6, 335);
      }
      brush.endShape(true);
      brush.fillTexture(0.8, 0);
      brush.fillBleed(0.3);
      let light = '#f0e554';
      brush.fillStyle(light);
      brush.fillTexture(0.7, 1);
      brush.fillRect(150, 350, 100, 30);
      brush.fillTexture(1, 1);
      brush.beginShape();
      for (let i = 0; i < 20; i++) {
        brush.vertex(i * 6, 380);
      }
      brush.endShape(true);
      brush.fillTexture(0.7, 1);
    },
    mousePressed: function () {
      canvas.mousePressed(i => {
        if (p5.yahoo && typeof p5.yahoo.raise == 'function') {
          p5.yahoo.raise(p5.java);
        }
      });
    }
  };
  sketch.setup();
  sketch.draw();
})();
