  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // sky
  fillTexture(1, true);
  brush.beginShape(1);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);
  fillTexture(1, false);

  // ground
  fillTexture(0, true);
  brush.beginShape(0.5);
  brush.vertex(0, 400);
  brush.vertex(400, 400);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.endShape(true);

  // hills
  brush.fill("coral", 0.6);
  brush.circle(200, 200, 100);
  brush.fill("skyblue", 0.6);
  brush.circle(220, 150, 80);
  brush.fill("skyblue", 0.6);
  brush.circle(220, 250, 80);
  brush.fill("skyblue", 0.6);
  brush.circle(200, 300, 70);
  brush.fill("skyblue", 0.6);
  brush.circle(180, 250, 70);
  brush.fill("skyblue", 0.6);
  brush.circle(180, 350, 70);

  // painting
  brush.beginShape(0.5);
  brush.vertex(-300, 200);
  brush.vertex(-200, 150);
  brush.vertex(-100, 300);
  brush.vertex(0, 350);
  brush.vertex(200, 300);
  brush.vertex(300, 200);
  brush.endShape(true);
}

